style.css:
@-moz-document url-prefix("https://www.youtube.com/feed/channels") {
div#primary {
    counter-reset: number;
}

div#primary #avatar-section::before {
    counter-increment: number;
    content: counter(number) ". ";
    color: white;
    text-shadow: 0 0 10px black, 0 0 10px black;
    font-size: 2em;
    position: absolute;
}
}
